TLM.f("Sancti/08-13",{"officium":"Ss. Hippolyti et Cassiani Martyrum","rule":["Gloria"],"fallback":"Commune/C3b","from":{"Introitus":"Commune/C3b","Lectio":"Commune/C3b","Graduale":"Commune/C3b","Tractus":"Commune/C3b","Evangelium":"Commune/C3b","Offertorium":"Commune/C3b","Communio":"Commune/C3b"},"sections":{"Introitus":[{"k":"ref","la":"Ps 36:39"},{"k":"text","la":"Salus autem justórum a Dómino: et protéctor eórum est in témpore tribulatiónis."},{"k":"ref","la":"Ps 36:1"},{"k":"text","la":"Noli æmulári in malignántibus: neque zeláveris faciéntes iniquitátem."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Salus autem justórum a Dómino: et protéctor eórum est in témpore tribulatiónis."}],"Oratio":[{"k":"text","la":"Da, quǽsumus, omnípotens Deus: ut beatórum Mártyrum tuórum Hippolýti et Cassiáni veneránda sollémnitas, et devotiónem nobis áugeat et salútem."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Hebrǽos"},{"k":"ref","la":"Hebr 10:32-38"},{"k":"text","la":"Fratres: Rememorámini prístinos dies, in quibus illumináti magnum certámen sustinuístis passiónum: et in áltero quidem oppróbriis et tribulatiónibus spectáculum facti: in áltero autem sócii táliter conversántium effécti. Nam et vinctis compássi estis, et rapínam bonórum vestrórum cum gáudio suscepístis, cognoscéntes vos habere meliórem et manéntem substántiam. Nolíte itaque amíttere confidéntiam vestram, quæ magnam habet remuneratiónem. Patiéntia enim vobis necéssaria est: ut, voluntátem Dei faciéntes, reportétis promissiónem. Adhuc enim módicum aliquántulum, qui ventúrus est, véniet, et non tardábit. Justus autem meus ex fide vivit."}],"Graduale":[{"k":"ref","la":"Ps 33:18-19"},{"k":"text","la":"Clamavérunt justi, et Dóminus exaudívit eos: et ex ómnibus tribulatiónibus eórum liberávit eos."},{"k":"text","la":"Juxta est Dóminus his, qui tribuláto sunt corde: et húmiles spíritu salvábit. Allelúja, allelúja.","mark":"V"},{"k":"text","la":"Te Mártyrum candidátus laudat exércitus, Dómine. Allelúja.","mark":"V"}],"Tractus":[{"k":"ref","la":"Ps 33:18-19"},{"k":"text","la":"Clamavérunt justi, et Dóminus exaudívit eos: et ex ómnibus tribulatiónibus eórum liberávit eos."},{"k":"text","la":"Juxta est Dóminus his, qui tribuláto sunt corde: et húmiles spíritu salvábit.","mark":"V"},{"k":"ref","la":"Ps 125:5-6"},{"k":"text","la":"Qui séminant in lácrimis, in gáudio metent."},{"k":"text","la":"Eúntes ibant et flébant, mitténtes sémina sua.","mark":"V"},{"k":"text","la":"Veniéntes autem vénient cum exsultatióne, portántes manípulos suos.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 12:1-8"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Atténdite a ferménto pharisæórum, quod est hypócrisis. Nihil autem opértum est, quod non revelétur: neque abscónditum, quod non sciátur. Quóniam, quæ in ténebris dixístis, in lúmine dicéntur: et quod in aurem locúti estis in cubículis, prædicábitur in tectis. Dico autem vobis amícis meis: Ne terreámini ab his, qui occídunt corpus, et post hæc non habent ámplius quid fáciant. Osténdam autem vobis, quem timeátis: timéte eum, qui postquam occíderit, habet potestátem míttere in gehénnam. Ita dico vobis: hunc timéte. Nonne quinque pásseres véneunt dipóndio, et unus ex illis non est in oblivióne coram Deo? Sed et capílli cápitis vestri omnes numeráti sunt. Nolíte ergo timére: multis passéribus pluris estis vos. Dico autem vobis: Omnis, quicúmque conféssus fúerit me coram homínibus, et Fílius hóminis confitébitur illum coram Angelis Dei."}],"Offertorium":[{"k":"ref","la":"Sap 3:1-3"},{"k":"text","la":"Justórum ánimæ in manu Dei sunt, et non tanget illos torméntum malítiae: visi sunt óculis insipiéntium mori: illi autem sunt in pace, allelúja."}],"Secreta":[{"k":"text","la":"Réspice, Dómine, múnera pópuli tui, Sanctórum festivitáte votíva: et tuæ testificátio veritátis nobis profíciat ad salútem."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Matt 10:27"},{"k":"text","la":"Quod dico vobis in ténebris, dícite in lúmine, dicit Dóminus: et quod in aure audítis, prædicáte super tecta."}],"Postcommunio":[{"k":"text","la":"Sacramentórum tuórum, Dómine, commúnio sumpta nos salvet: et in tuæ veritátis luce confírmet."},{"k":"macro","name":"Per Dominum"}]},"hr":{"6014aaebd2386e76":{"t":"<i>Pomolimo se</i>.\nDaj, molimo, svemogući Bože, da nam časna svetkovina blaženih mučenika tvojih Hipolita i Kasijana uveća pobožnost i spasenje.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"64a125b5712f4b56":{"t":"Pogledaj, Gospodine, darove svoga naroda, koje ti posvećuje o svetkovini svetih, i neka nam za spasenje koristi njihovo svjedočanstvo tvoje istine.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"06d08928950bdc39":{"t":"<i>Pomolimo se</i>.\nPrimanje tvojih otajstava, Gospodine, neka nas spasi i utvrdi u svjetlu tvoje istine.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
